def main():
    p = pathlib.Path(__file__).parent / "seed" / "letters_seed.json"
    rows = json.loads(p.read_text())
    counts = {}
    for row in rows:
        lid = row["id"]
        if lid not in T:
            continue
        notes = row.setdefault("notes", {})
        for lang, note in T[lid].items():
            notes[lang] = note
        counts[lid] = len(notes)
    p.write_text(json.dumps(rows, indent=2, ensure_ascii=False) + "\n")
    print("letter notes coverage after batch 1:")
    for lid in T:
        print(f"  {lid:8s} → {counts.get(lid, 0)} langs")


if __name__ == "__main__":
    main()
